package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import jakarta.persistence.EntityManager;

class TmpBulkWarnTest extends AcceptanceBase {

	@Autowired
	EntityManager em;

	@Test
	void over80GetsWarning() throws Exception {
		createMany(81);
		int id = createOwnerOk(ownerNode());
		Object cnt = em.createNativeQuery(
			"select count(*) from owners o2 where o2.registration_date = "
			+ "(select registration_date from owners where id = " + id + ") and o2.id < " + id).getSingleResult();
		Object expr = em.createNativeQuery(
			"select (select count(*) from owners o2 where o2.registration_date = o1.registration_date and o2.id < o1.id) > 80 "
			+ "from owners o1 where o1.id = " + id).getSingleResult();
		System.out.println("TMP id=" + id + " earlierSameDate=" + cnt + " exprGt80=" + expr);
	}
}

